const seen = new Map<number, { closed_at: string | null; state: string }>();
let page: number | null = 1;
let pages = 0;
let rawCount = 0;
while (page !== null && pages < 100) {
  const res = await tools.list_issues({ repo: "acme/cli", state: "closed", page });
  for (const it of res.items) {
    rawCount++;
    if (!seen.has(it.number)) {
      seen.set(it.number, { closed_at: it.closed_at, state: it.state });
    }
  }
  page = res.next_page;
  pages++;
}
const uniq = [...seen.entries()].map(([number, v]) => ({ number, ...v }));
const inOct = uniq.filter(
  (r) => r.closed_at !== null && r.closed_at >= "2026-10-01T00:00:00Z" && r.closed_at < "2026-11-01T00:00:00Z"
);
const nonClosedState = uniq.filter((r) => r.state !== "closed").length;
const nullClosedAt = uniq.filter((r) => r.closed_at === null).length;
return {
  pages,
  rawCount,
  uniqueCount: uniq.length,
  oct_count: inOct.length,
  nonClosedState,
  nullClosedAt,
  oct_numbers: inOct.map((r) => r.number).sort((a, b) => a - b),
};
